INSERT INTO `country_contents` VALUES
(147,1,9,'Türkiye coğrafyası, Türkiye\'nin konumu, coğrafi bölgeleri, yeryüzü şekilleri, iklim, nüfus, din, tarım, hayvancılık ve ekonomisinin yörelere ve bölgelere göre dağılımını içerir..'),
(148,1,10,'Kuzey Anadolu Dağları ya da Pontus Alpleri, Anadolu\'nun kuzeyini kıyıya paralel, birkaç sıra halinde kuşatan sıradağlarıdır. Orojenez sonucu oluşan bu kıvrım dağları batıdan doğuya şöyle sıralanır: Köroğlu Dağları, Ilgaz Dağları, Küre Dağları, Canik Dağları, Köse Dağları, Giresun Dağları, Doğu Karadeniz Dağları, Mescit Dağı, Yalnızçam Dağları, Tecer, Mercan, Allahuekber Dağları. Akarsu, çay, dere veya nehir için kullanılan ortak bir terimdir. Yeryüzünde sürekli veya aralıklı olarak akan su yolunu ifade eder ve su döngüsünün en önemli[kime göre?] parçasıdır.'),
(149,1,12,'Türk kültürü, kökeni Orta Asya\'nın kültürel birikimine dayanan bir kültürdür. Selçuklu döneminden itibaren Doğu Akdeniz ve İslam kültürleri ile etkileşim halinde olup Modern Türkiye\'ye kadar gelişti..'),
(150,1,13,'Türk mutfağı, Türkiye\'nin ulusal mutfağıdır. Orta Asya, Selçuklu ve Beylikler ile Osmanlı kültürünün mirasçısı olan Cumhuriyet Dönemi Türk Mutfağı hem Balkan ve Orta Doğu mutfaklarını etkilemiş hem de bu mutfaklardan etkilenmiştir.'),
(151,1,15,'Türkiye Cumhuriyeti\'nin topraklarını oluşturan bölgenin tarihi olarak anlaşılan Türkiye tarihi, hem Anadolu\'nun hem de Doğu Trakya\'nın tarihini içerir. Daha önce siyasi olarak farklı olan bu iki bölge, MÖ 2.'),
(152,2,9,'Japonya, Doğu Asya kıyılarında kıtanın Pasifik sahili boyunca uzanan ve stratovolkanik takımadalardan oluşan bir ada ülkesidir. Kuzey enlemi 24 °-46 ° ve doğu boylamı 123 °-146 ° arasındadır.'),
(153,2,10,'Fuji Dağı , Honshu adasında bulunan, 3.776 m yüksekliğiyle Japonya’daki en yüksek dağdır. Asya adalarında bulunan ikinci en yüksek yanardağdır ve dünya üzerindeki en yüksek yedinci ada doruğunu oluşturur. Kuma Nehri, Japonya\'nın Kumamoto prefektörlüğünde bulunan bir nehirdir. Nehir, Choushigasa Dağı\'ndan başlayarak Yatsushiro\'da Yatsushiro Denizi\'ne dökülmektedir.'),
(154,2,12,'Japonya tarihi antik zamanların şehir devletlerinin modern Japon ulus devletine ulaşacak şekilde coğrafi ve sosyal tarihini anlatmaktadır..'),
(155,2,13,'Japon mutfağı, Japonya\'ya özgü yemek pişirme tarzıdır. Japonya\'nın geleneksel mutfağı (washoku), miso çorbası ve diğer yemekler ile pilav üzerine kuruludur ve mevsimlik malzemelere vurgu yapılmaktadır.'),
(156,2,15,'Japonya tarihi antik zamanların şehir devletlerinin modern Japon ulus devletine ulaşacak şekilde coğrafi ve sosyal tarihini anlatmaktadır..'),
(157,3,9,'Yukarı Mısır, Mısır\'da adı ile de bilinen Nil Irmağı vadisinin iki yanı boyunca uzanan, güney ucunda Nübye ve kuzey yönüne doğru akan Nil\'in Akdeniz\'e ulaşmasından önce başlayan Aşağı Mısır bölgesine kadar uzanan bölgeye verilen isimdir..'),
(158,3,10,'Mısır, resmî adıyla Mısır Arap Cumhuriyeti, Afrika\'nın kuzeydoğu köşesi ile Sina Yarımadası üzerinden Asya\'nın güneybatı köşesini kapsayan bir ülkedir. Kuzeyde Akdeniz, kuzeydoğuda Filistin ve İsrail, doğuda Kızıldeniz, güneyde Sudan ve Sahra Çölü, batıda ise Libya ile çevrilidir. Mısır, resmî adıyla Mısır Arap Cumhuriyeti, Afrika\'nın kuzeydoğu köşesi ile Sina Yarımadası üzerinden Asya\'nın güneybatı köşesini kapsayan bir ülkedir. Kuzeyde Akdeniz, kuzeydoğuda Filistin ve İsrail, doğuda Kızıldeniz, güneyde Sudan ve Sahra Çölü, batıda ise Libya ile çevrilidir.'),
(159,3,12,'Nakada kültürü ismini Kina, Nakada kasabasından alan, arkeolojik bir Kalkolitik Hanedan öncesi Mısır kültürü..'),
(160,3,13,'Mısır mutfağı, Mısır\'a özgü yemek pişirme tarzıdır. Mısır mutfağı, Mısır\'ın zengin Nil Vadisi ve Nil Deltası\'ndan gelen baklagil, sebze ve meyvelerden yoğun olarak yararlanır.'),
(161,3,15,'Mısır tarihi, verimli Nil Nehri kıyıları ve deltası ile Mısır\'ın yerli halkının başarıları ile uzun ve zengin olmuştur. Mısır hiyeroglifleri Rosetta Taşı\'nın keşfi ve yardımıyla deşifre edilene kadar Mısır\'ın eski tarihinin çoğu bir gizemdi.'),
(162,4,9,'Arnavutluk 28,750 kilometrekare alana sahip bir ülkedir. Komşuları kuzeyde 287 kilometre ile Sırbistan ve Karadağ, kuzey ve doğuda 151 kilometre ile Kuzey Makedonya, güney ve güneydoğuda 282 kilometre ile Yunanistan\'dır.'),
(163,4,10,'Apenin Dağları veya Apeninler, İtalya Yarımadası\'nda bir dağ zinciridir. Alplerin bir koludur.. İtalya, resmî adıyla İtalyan Cumhuriyeti, Güney Avrupa\'da, büyük ölçüde İtalya Yarımadası üzerinde yer alan bir ülke. Akdeniz\'in en büyük iki adası Sicilya ve Sardinya da İtalyan topraklarıdır.'),
(164,4,12,'Avrupa kültürü, Avrupa anakarası üzerinde bulunan ulusların öz kültürlerinin birbirleriyle olan ortak noktaları ya da birbirine geçerek oluşturduğu ortak birikim olarak tanımlanabilir. Avrupa kültürü başlıbaşına Batı Kültürünün kendisi ya da kaynağı olarak nitelendirilebilir.'),
(165,4,13,'İtalyan mutfağı, kökeni MÖ 4. yüzyıla kadar uzanan, toplumsal ve siyasi değişimlerle yüzyıllar içerisinde gelişmiş, dünyanın her tarafında bilinen, sevilen, oldukça zengin bir mutfaktır.'),
(166,4,15,'İtalya tarihi, İtalya yarımadasında yaşayan halkların antik çağlardan başlayarak günümüze kadar ulaşan tarihini kapsar..'),
(167,5,9,'Brezilya, Güney Amerika\'nın en büyük ülkesidir. Yüzölçümü olarak dünyanın 5.'),
(168,5,10,'Brezilya, resmî adıyla Brezilya Federatif Cumhuriyeti, Güney Amerika\'nın en büyük ülkesidir. Ayrıca yüzölçümü bakımından dünyanın beşinci, nüfus bakımından ise yedinci büyük ülkesidir ve 213 milyondan fazla insanı barındırmaktadır. Brezilya\'nın vahşi yaşamı oldukça çeşitlidir. 8,514,877 km² yüzölçümüyle en geniş 5.'),
(169,5,12,'Brezilya bayrağı günümüzde kullanılan hâli ile 11 Mayıs 1992 tarihinde göndere çekilerek kullanılmaya başlanan Brezilya resmi devlet bayrağıdır..'),
(170,5,13,'Brezilya mutfağı, Avrupa, Afrika ve Kızılderili mutfaklarının etkilerini taşır. Ülkenin yerli halkının çeşitliliği, göçmen nüfusu ve ayrıca büyük yüzölçümü nedeniyle bölgeden bölgeye ciddi farklılıklar gösterir.'),
(171,5,15,'Brezilya tarihi, günümüzdeki insanlık tarihinin Brezilya topraklarında gerçekleşen kısmıdır..'),
(177,1,17,'Türkiye ekonomisi, üst-orta gelirli, karma piyasalı ve gelişmekte olan bir ekonomidir. OECD ve G20\'nin kurucu üyesi olan Türkiye, aynı zamanda E7 ülkeleri, GOBLE\'ler ve YSÜ\'ler arasında sayılmaktadır.'),
(178,1,18,'Türkiye Cumhuriyeti Tarım ve Orman Bakanlığı, Türkiye Cumhuriyeti Cumhurbaşkanlığına bağlı olarak çalışan, tarım ve orman işlerinden sorumlu olan bakanlık. Gıda, Tarım ve Hayvancılık ile Orman ve Su İşleri bakanlıklarının teşkilat ve görevlerine ilişkin yasal düzenlemelerin yürürlükten kaldırılması sonrasında, 1 sayılı Cumhurbaşkanlığı Kararnamesiyle yeniden yapılandırılmıştır.. Türkiye Vagon Sanayisi A.Ş. ya da kısaltmasıyla TÜVASAŞ, Adapazarı merkezli, TCDD\'nin bağlı ortaklığında KİT vagon üreticisi eski anonim şirket.'),
(184,2,17,'Japonya ekonomisi, IMF’nin 2025 yılı projeksiyonlarına göre nominal olarak dünyanın dördüncü büyük ve satın alma gücü paritesi bakımından beşinci büyük ekonomisidir. Ülke, Amerika Birleşik Devletleri\'nin ardından dünyanın ikinci büyük gelişmiş ekonomisi olma statüsünü korumaktadır.'),
(185,2,18,'Japonya\'da tarım, ormancılık ve balıkçılık, Japonya\'da madencilik endüstrisiyle birlikte Japonya ekonomisinin birincil sektörünü oluştururlar, ancak birlikte gayrisafi millî hasılanın yalnızca %1,3\'ünü oluştururlar. Japonya\'nın topraklarının yalnızca %20\'si ekime uygundur ve tarım ekonomisi büyük ölçüde sübvanse edilir.. Tamano, Japonya\'nın Okayama prefektörlüğünde bulunan bir şehirdir. Şehir 3 Ağustos 1940 tarihinde kurulmuştur.'),
(191,3,17,'Mısır ekonomisi, ortalama bir büyüme seviyesine sahip karma bir ekonomidir. Mısır ekonomisi, Cumhurbaşkanı Cemal Abdünnasır yönetimindeki ithal ikamesine odaklanan, merkezi bir planlı ekonomi olup 1990\'larda, bir dizi Uluslararası Para Fonu düzenlemeleri, Mısır\'ın Körfez Savaşı koalisyonuna katılımından kaynaklanan devasa dış borç hafifletmesi ülkenin makroekonomik performansını geliştirmesine yardımcı oldu..'),
(192,3,18,'Mısır, resmî adıyla Mısır Arap Cumhuriyeti, Afrika\'nın kuzeydoğu köşesi ile Sina Yarımadası üzerinden Asya\'nın güneybatı köşesini kapsayan bir ülkedir. Kuzeyde Akdeniz, kuzeydoğuda Filistin ve İsrail, doğuda Kızıldeniz, güneyde Sudan ve Sahra Çölü, batıda ise Libya ile çevrilidir. Mısır, resmî adıyla Mısır Arap Cumhuriyeti, Afrika\'nın kuzeydoğu köşesi ile Sina Yarımadası üzerinden Asya\'nın güneybatı köşesini kapsayan bir ülkedir. Kuzeyde Akdeniz, kuzeydoğuda Filistin ve İsrail, doğuda Kızıldeniz, güneyde Sudan ve Sahra Çölü, batıda ise Libya ile çevrilidir.'),
(198,4,17,'İtalya ekonomisi, Euro bölgesindeki en büyük 3. ulusal ekonomi, nominal GSYİH\'ya göre dünyanın en büyük 8.'),
(199,4,18,'İtalya, resmî adıyla İtalyan Cumhuriyeti, Güney Avrupa\'da, büyük ölçüde İtalya Yarımadası üzerinde yer alan bir ülke. Akdeniz\'in en büyük iki adası Sicilya ve Sardinya da İtalyan topraklarıdır. Bari, İtalya\'nın güneydoğusunda Adriyatik Denizi kenarında bir liman kentidir. Puglia bölgesinin ve aynı adlı Bari ilinin merkezidir.'),
(205,5,17,'Brezilya ekonomisi, gayri safi yurtiçi hasıla ölçümüyle dünyanın en büyük on ikinci ve 2020\'de satın alma gücü paritesine göre de yine dünyanın sekizinci en büyük ekonomisidir. Gayri safi yurt içi hasıla bakımından Latin Amerika\'nın en büyük ekonomisi olan Brezilya ekonomisi gelişmekte olan bir karma ekonomidir.'),
(206,5,18,'Brezilya, resmî adıyla Brezilya Federatif Cumhuriyeti, Güney Amerika\'nın en büyük ülkesidir. Ayrıca yüzölçümü bakımından dünyanın beşinci, nüfus bakımından ise yedinci büyük ülkesidir ve 213 milyondan fazla insanı barındırmaktadır. Natal, Brezilya\'nın Rio Grande do Norte eyaletinde bulunan ve eyalete başkentlik yapan belediye. Nüfus 2020 sayımına göre 890.480 idi.'),
(207,6,9,'Pakistan coğrafyası, kuzeydoğusundaki Çin, kuzeybatısında ve batısındaki Afganistan, doğusundaki Hindistan ve güneybatısındaki İran sınırında yer alır..'),
(208,6,10,'Afganistan, resmî adıyla Afganistan İslam Emirliği, Orta Asya ve Güney Asya\'nın kesiştiği noktada yer alan ve denize kıyısı olmayan bir ülkedir. Doğu ve güneyde Pakistan, batıda İran, kuzeybatıda Türkmenistan, kuzeyde Özbekistan, kuzeydoğuda Tacikistan ve kuzeydoğu ve doğuda Çin ile komşudur. Afganistan, resmî adıyla Afganistan İslam Emirliği, Orta Asya ve Güney Asya\'nın kesiştiği noktada yer alan ve denize kıyısı olmayan bir ülkedir. Doğu ve güneyde Pakistan, batıda İran, kuzeybatıda Türkmenistan, kuzeyde Özbekistan, kuzeydoğuda Tacikistan ve kuzeydoğu ve doğuda Çin ile komşudur.'),
(209,6,12,'Afganistan\'ın kültürü yüzyıllardır varlığını sürdürüyor ve ülkenin kültürel çeşitliliğini kapsar. Afganistan\'ın kültürü, aynı dine sahip olmak da dahil olmak üzere, yakınlardaki Pers ile tarihsel olarak güçlü bir şekilde bağlantılıdır, çünkü her iki ülkenin insanları binlerce yıldır birlikte yaşamıştır.'),
(210,6,13,'Afgan mutfağı; büyük oranda Afganistan\'da yetişen tarım ürünleriyle yapılan yemeklerden oluşur. Afganistan\'ın üreticisi olduğu en popüler besinler; buğday, arpa, pirinç ve mısırdır.'),
(211,6,15,'Afganistan tarihi, yazılı olarak izleri bölgenin Ahameniş İmparatorluğu hakimiyeti altında olduğu MÖ 500\'lü yıllara kadar süren bir tarihtir fakat MÖ 3000 ile 2000 yılları arasında topraklarında ileri düzeyde kentleşmiş bir kültürün var olduğuna dair kanıtlar da bulunmaktadır. Büyük İskender ve ordusu, Gaugamela Savaşı\'nda Pers İmparatorluğu\'nu yenilgiye uğrattıktan sonra MÖ 330 yılında Afganistan\'a ulaştı.'),
(212,6,17,'Afganistan 32 milyondan fazla nüfusa ve 46 kişi/km² nüfus yoğunluğuna sahiptir..'),
(213,6,18,'Afganistan, resmî adıyla Afganistan İslam Emirliği, Orta Asya ve Güney Asya\'nın kesiştiği noktada yer alan ve denize kıyısı olmayan bir ülkedir. Doğu ve güneyde Pakistan, batıda İran, kuzeybatıda Türkmenistan, kuzeyde Özbekistan, kuzeydoğuda Tacikistan ve kuzeydoğu ve doğuda Çin ile komşudur. Bagrami, Afganistan\'ın Kabil Vilayeti\'nde şehir..'),
(214,7,9,'Bu madde Almanya coğrafyasını anlatmaktadır..'),
(215,7,10,'Doğu Almanya veya resmî adıyla Demokratik Alman Cumhuriyeti, günümüzdeki Almanya\'nın doğu kısmında bulunmuş, 1949 ile 1990 yılları arasında var olmuş sosyalist cumhuriyet. ADC; 1945\'te II. Main Nehri, orta Almanya\'da 527 km uzunluğunda batıdan doğuya doğru akan ve Ren Nehri ile Tuna Nehrini bağlayan nehirdir. Main Nehri, Bavyera, Baden-Württemberg ve Hessen eyaletleri boyunca akar.'),
(216,7,12,'Almanya tarihi, Cermenlerin ilk olarak Roma İmparatorluğu döneminde devlet kurmalarıyla başlar. Kutsal Roma Cermen İmparatorluğu dönemiyle 1806 yılına kadar devam eder.'),
(217,7,13,'Alman mutfağı, Alman ulusunun yemek tarzından ileri gelmektedir. Yüzyıllar boyunca bölgeden bölgeye gerçekleşen sosyal ve politik değişiklikler etkisiyle mutfak gelişimini sürdürmüştür.'),
(218,7,15,'Almanya tarihi, Cermenlerin ilk olarak Roma İmparatorluğu döneminde devlet kurmalarıyla başlar. Kutsal Roma Cermen İmparatorluğu dönemiyle 1806 yılına kadar devam eder.'),
(219,7,17,'Almanya ekonomisi son derece gelişmiş bir sosyal piyasa ekonomisidir. Almanya, dolar kuru üzerinden yapılan hesaplamalara göre dünyanın üçüncü büyük ekonomisine sahiptir.'),
(220,7,18,'Doğu Almanya veya resmî adıyla Demokratik Alman Cumhuriyeti, günümüzdeki Almanya\'nın doğu kısmında bulunmuş, 1949 ile 1990 yılları arasında var olmuş sosyalist cumhuriyet. ADC; 1945\'te II. Hamm, Almanya\'nın kuzeybatısında, Kuzey Ren-Vestfalya eyaletinde bir kent..'),
(221,8,9,'Amerika Birleşik Devletleri, Kıta ABD\'si, Alaska, Hawaii eyaletleri ile diğer ada bölgelerinden oluşmaktadır. Amerika Birleşik Devletleri, Kanada ve Meksika ile kara sınırlarını, bunlara ek olarak Rusya, Küba ve Bahamalar ile deniz sınırlarını paylaşmaktadır.'),
(222,8,10,'Atlas Dağları, Afrika kıtasının kuzeybatısında, Fas, Cezayir ve Tunus ülkelerinden geçen büyük bir dağ sırasıdır.. Río de la Plata Güney Amerika nehirleri Rio Paraná ve Rio Uruguay\'ın beraber oluşturdukları 290 km uzunluğunda ve 220 kilometreye varan genişlikte, Atlas Okyanusu\'na açılan nehir ağzı. Kuzeydoğusunda Uruguay\'ın başkenti Montevideo, güneybatı yakasında ise Arjantin\'in başkenti Buenos Aires şehirleri bulunmaktadır.'),
(223,8,12,'Kuzey Amerika yerlileri ya da Kuzey Amerika Kızılderilileri, Kuzey Amerika\'da Kanada, Grönland, ABD ve Meksika\'nın kuzeyindeki Amerika yerlileri grubundan yerli halklar ve bunlar tarafından ortaya konan kültür bölgesi. Kültürüne göre 10 alt bölgeye ayrılır ve Eskimo-Aleut halklarının oluşturduğu Arktik kültür bölgesi hariç diğer dokuzu Kızılderililere ait kültürlerdir.'),
(224,8,13,'Kuzey Amerika mutfağı, Birleşik Devletler, Kanada ve Meksika gibi Kuzey Amerika ülkelerine özgü yiyeceklerin toplu adı. Avrupa mutfağıyla birçok ortak özellik barındıran Kuzey Amerika mutfağı Yerli Amerika mutfağı, Yahudi mutfağı ve Asya mutfağından da izler taşımaktadır..'),
(225,8,15,'Amerika tarihi ilk insan yerleşimlerinden modern dönemdeki devletlere kadarki dönemi kapsar. İnsanların Bering Boğazı\'ndan geçip Sibirya üzerinden Alaska\'ya geçişi ile Amerikan tarihi başlar.'),
(226,8,17,'Bu, Amerika kıtasındakı menkul kıymetler borsaların bir listesidir. Latin Amerika\'daki menkul kıymetler borsaları \"Bolsa de Valores\" terimi kullanır..'),
(227,8,18,'Amerika Birleşik Devletleri Tarım Bakanlığı, ABD federal hükûmetinin tarım, çiftçilik, ormancılık ve besin maddeleri politikalarını geliştirip idare etmekle yükümlü ABD federal yönetim dairesi. Hedefleri çiftçilerin ve besi hayvanı yetiştiricilerinin gereksinimlerini sağlamak, tarım ürünleri ticaretini ve üretimini teşvik etmek, besin maddelerinin sağlıklı olmasını temin ve kontrol etmek, doğal kaynakları korumak, kırsal alandaki topluluklara destek sağlamak ve ABD\'de ve dış ülkelerde açlığa son vermek olarak verilmiştir.. Hamm, Almanya\'nın kuzeybatısında, Kuzey Ren-Vestfalya eyaletinde bir kent..'),
(228,9,9,'Birleşik Krallık, Batı Avrupa\'nın kuzeybatısında Britanya Adaları\'nda bulunan bir ada ülkesidir. Enlemi 49 °-59 ° ve boylamı 8 °-2 ° arasındadır.'),
(229,9,10,'Catskill Dağları, ,Amerika Birleşik Devletleri\'nin New York eyaletinde alçak bir dağ silsilesi olan Appalaş Dağları\'nın etekleridir.. Dünyanın en uzun nehirleri listesi dünyada bulunan 1.000 km\'den daha uzun olan nehir sistemlerini ihtiva eder. Uzunluk kavramı karmaşık ve tartışmalıdır.'),
(230,9,12,'Birleşik Krallık ya da diğer adıyla Kuzey İrlanda ve Büyük Britanya Birleşik Krallığı kültürü, Birleşik Krallık topraklarında yaşayanların ortak kültürüdür. Genel olarak İngiliz Kültürü olarak da bilinmektedir.'),
(231,9,13,'Amerikan mutfağı, Amerika Birleşik Devletleri\'nde (ABD) yaşayanlara özgü bir mutfaktır. ABD\'de yaygın olan pişirme stilleri, diğer Batı ülkelerindekilerine benzer.'),
(232,9,15,'Dünyadaki birçok ülke gibi, Birleşik Arap Emirlikleri\'nin modern tarihi şu anki Yahudi nüfusunu ifşa etmemektedir. Bin yıl süresince Orta Doğu\'daki Yahudi tarihi ve Arap Yarımadası\'ndaki Yahudi tarihinde Yahudi cemaatlerinin bugün BAE topraklarında toplandıkları kayıtlarda yer almaktadır..'),
(233,9,17,'Avrupa Birliği ekonomisi, Uluslararası Para Fonu (IMF)\'na göre satın alma gücü paritesi bazında 12,256 milyar euroluk bir gayri safi yurt içi hasıla meydana getirir. Avrupa Birliği ekonomisi bir ortak pazara sahiptir ve Dünya Ticaret Örgütü tarafından bir bütün olarak değerlendirmeye alınmaktadır..'),
(234,9,18,'Amerika Birleşik Devletleri Tarım Bakanlığı, ABD federal hükûmetinin tarım, çiftçilik, ormancılık ve besin maddeleri politikalarını geliştirip idare etmekle yükümlü ABD federal yönetim dairesi. Hedefleri çiftçilerin ve besi hayvanı yetiştiricilerinin gereksinimlerini sağlamak, tarım ürünleri ticaretini ve üretimini teşvik etmek, besin maddelerinin sağlıklı olmasını temin ve kontrol etmek, doğal kaynakları korumak, kırsal alandaki topluluklara destek sağlamak ve ABD\'de ve dış ülkelerde açlığa son vermek olarak verilmiştir.. Hamm, Almanya\'nın kuzeybatısında, Kuzey Ren-Vestfalya eyaletinde bir kent..'),
(235,10,9,'Amerika Birleşik Devletleri, Kıta ABD\'si, Alaska, Hawaii eyaletleri ile diğer ada bölgelerinden oluşmaktadır. Amerika Birleşik Devletleri, Kanada ve Meksika ile kara sınırlarını, bunlara ek olarak Rusya, Küba ve Bahamalar ile deniz sınırlarını paylaşmaktadır.'),
(236,10,10,'Catskill Dağları, ,Amerika Birleşik Devletleri\'nin New York eyaletinde alçak bir dağ silsilesi olan Appalaş Dağları\'nın etekleridir.. Dünyanın en uzun nehirleri listesi dünyada bulunan 1.000 km\'den daha uzun olan nehir sistemlerini ihtiva eder. Uzunluk kavramı karmaşık ve tartışmalıdır.'),
(237,10,12,'Sintaşta kültürü, Sintaşta-Petrovka kültürü ya da Sintashta-Arkaim kültürü, Doğu Avrupa ve Orta Asya\'da MÖ 2100-1800 yılları arasında var olmuş Tunç Çağı arkeolojik kültürü. Kültürün adı, Rusya\'nın Çelyabinsk Oblastı\'nda bulunan Sintashta arkeolojik sit alanından gelmektedir..'),
(238,10,13,'Amerikan mutfağı, Amerika Birleşik Devletleri\'nde (ABD) yaşayanlara özgü bir mutfaktır. ABD\'de yaygın olan pişirme stilleri, diğer Batı ülkelerindekilerine benzer.'),
(239,10,15,'Amerika Birleşik Devletleri tarihi veya kısaca Birleşik Devletler tarihi, Amerika Birleşik Devletleri\'nin kurulduğu Kuzey Amerika topraklarının üzerinde, tarih öncesi dönemlerden günümüze kadar uzanan geçmişi. Amerika\'nın 15.'),
(240,10,17,'Amerika Birleşik Devletleri ekonomisi, oldukça gelişmiş bir liberal-kapitalist piyasa ekonomisidir. Nominal olarak dünyanın en büyük ve satınalma gücü paritesi bakımından ikinci büyük ekonomisi olup nominal olarak dünya GSYİH\'sinin %22\'sini oluşturmaktadır..'),
(241,10,18,'Amerika Birleşik Devletleri Tarım Bakanlığı, ABD federal hükûmetinin tarım, çiftçilik, ormancılık ve besin maddeleri politikalarını geliştirip idare etmekle yükümlü ABD federal yönetim dairesi. Hedefleri çiftçilerin ve besi hayvanı yetiştiricilerinin gereksinimlerini sağlamak, tarım ürünleri ticaretini ve üretimini teşvik etmek, besin maddelerinin sağlıklı olmasını temin ve kontrol etmek, doğal kaynakları korumak, kırsal alandaki topluluklara destek sağlamak ve ABD\'de ve dış ülkelerde açlığa son vermek olarak verilmiştir.. Azerbaycan Devlet Petrol ve Sanayi Üniversitesi, Azerbaycan\'ın başkenti Bakü\'de bulunan teknik bilimler ve petrol sanayisi yönlü devlet üniversitesi. Bundan önceki ismi Azerbaycan Devlet Petrol Akademisi idi..'),
(242,11,9,'İspanya coğrafyası, İspanya\'nın coğrafi özelliklerini tanımlar. İspanya, güneybatı Avrupa\'da yer alan ve İber Yarımadası\'nın büyük çoğunluğunu kapsayan bir ülkedir.'),
(243,11,10,'Andorra, resmi adıyla Andorra Prensliği, İber Yarımadası\'nda Pirene Dağları üzerinde denize kıyısı olmayan egemen bir mikrodevlettir. Kuzeyde Fransa, güneyde ise İspanya ile çevrilidir. Pont de la Tosca, Escaldes-Engordany Parişi, Andorra\'da bulunan bir köprüdür. Andorra Kültür Mirası\'nda kayıtlı bir miras varlığıdır.'),
(244,11,12,'Avrupa kültürü, Avrupa anakarası üzerinde bulunan ulusların öz kültürlerinin birbirleriyle olan ortak noktaları ya da birbirine geçerek oluşturduğu ortak birikim olarak tanımlanabilir. Avrupa kültürü başlıbaşına Batı Kültürünün kendisi ya da kaynağı olarak nitelendirilebilir.'),
(245,11,13,'Bu liste maddesi, Avrupa mutfaklarının bir listesidir. Mutfak, genellikle belirli bir kültürle ilişkilendirilen karakteristik pişirme uygulamaları ve geleneklere denmektedir.'),
(246,11,15,'Andorra tarihi bugünkü Andorra topraklarının tarih öncesi dönemlerden günümüze kadar uzanan tarihini kapsar..'),
(247,11,17,'Fransız frangı Fransa\'da kullanılan eski para birimidir. Fransız frangı ₣ veya F harfiyle gösterilirdi.'),
(248,11,18,'Andorra, resmi adıyla Andorra Prensliği, İber Yarımadası\'nda Pirene Dağları üzerinde denize kıyısı olmayan egemen bir mikrodevlettir. Kuzeyde Fransa, güneyde ise İspanya ile çevrilidir. Katalonya, İspanya\'ya bağlı İber Yarımadası\'nın kuzeydoğusunda yer alan özerk bölgedir. Katalonya 4 ilden oluşmaktadır: Barselona, Girona, Lleida ve Tarragona.'),
(249,12,9,'Güney Afrika, Afrika\'nın Güney bölgesidir. Coğrafik ve jeopolitik çeşitliliğe sahiptir.'),
(250,12,10,'Angola resmî adıyla Angola Cumhuriyeti, Güney Afrika\'nın batı kıyısında yer alan bir ülkedir. Toplam yüzölçümü ve nüfusu bakımından Brezilya\'dan sonra ikinci büyük Portekizce konuşan (Lusofon) ülkedir ve Afrika\'nın yedinci büyük ülkesidir. Kasai Nehri, Kongo Nehri\'nin bir koludur ve merkez Afrika\'da. Nehir, Angola\'dan başlar ve Angola ile Kongo Demokratik Cumhuriyeti arasında sınır görevi görür, daha sonra Kongo\'ya akarak, Kinşasa\'nın kuzeydoğusunda bulunan Kwamouth\'da Kongo Nehri\'ne katılır.'),
